439                  break;
440              }
441              sub = rx_sub.recv() => match sub {
442                  Ok(sub) => sub,
443                  Err(_) => break,
444              },
445              update = async {
446                  match &mut mailbox {
447                      Some(updates) => updates.changed().await.map(|()| *updates.borrow_and_update()),
448                      None => std::future::pending().await,
449                  }
450              } => {
451                  match update {
452                      Ok(true) => {
453                          sess.input_queue.notify_mailbox();
