36  impl WorldStateSection for AgentsMdState {
37      const ID: &'static str = "agents_md";
38      type Snapshot = AgentsMdSnapshot;
39  
40      fn matches_legacy_fragment(role: &str, text: &str) -> bool {
41          role == "user" && UserInstructions::matches_text(text)
42      }
43  
44      fn render_diff(
45          &self,
46          previous: PreviousSectionState<'_, Self::Snapshot>,
47      ) -> SectionTransition<Self::Snapshot> {
48          let current = match &self.instructions {
49              Some(instructions) => AgentsMdSnapshot {
50                  directory: instructions.directory.clone(),
51                  text: Some(instructions.text.clone()),
52              },
53              None => AgentsMdSnapshot::default(),
54          };
55          if matches!(previous, PreviousSectionState::Known(previous) if previous == &current) {
56              return (None, Vec::new());
57          }
58  
59          let previous_may_contain_instructions = match previous {
60              PreviousSectionState::Known(previous) => previous.text.is_some(),
61              PreviousSectionState::Unknown => true,
62              PreviousSectionState::Absent => false,
63          };
64          let instructions = match (&self.instructions, previous_may_contain_instructions) {
65              (Some(instructions), true) => UserInstructions {
66                  directory: instructions.directory.clone(),
67                  text: format!("{REPLACEMENT_NOTICE}\n\n{}", instructions.text),
68              },
69              (Some(instructions), false) => instructions.clone(),
70              (None, true) => UserInstructions {
71                  directory: None,
72                  text: REMOVAL_NOTICE.to_string(),
73              },
74              (None, false) => return (Some(current), Vec::new()),
75          };
76          (
77              Some(current),
78              vec![WorldStateUpdate::fragment(instructions)],
79          )
80      }
81  }
