1633  async fn run_sampling_request(
1634      sess: Arc<Session>,
1635      step_context: Arc<StepContext>,
1636      turn_store: Arc<codex_extension_api::ExtensionData>,
1637      turn_diff_tracker: SharedTurnDiffTracker,
1638      client_session: &mut ModelClientSession,
1639      input: Vec<ResponseItem>,
1640      cancellation_token: CancellationToken,
1641  ) -> CodexResult<(SamplingRequestResult, Vec<ResponseItem>)> {
1642      let turn_context = Arc::clone(&step_context.turn);
1643      let preempt = step_context.preempt.clone().unwrap_or_default();
1644      let _input_watch = if let Some(preempt) = &step_context.preempt {
1645          sess.input_queue
1646              .watch_user_input(&sess.active_turn, &turn_context.sub_id, preempt.clone())
1647              .await
1648      } else {
1649          None
1650      };
1651      let base_instructions = sess.get_prompt_base_instructions().await;
1652  
1653      let tool_runtime = ToolCallRuntime::new(
1654          Arc::clone(&sess),
1655          Arc::clone(&step_context),
1656          Arc::clone(&turn_diff_tracker),
1657      );
1658      let _code_mode_worker = sess.services.code_mode_service.start_turn_worker(
1659          &sess,
1660          Arc::clone(&step_context),
1661          Arc::clone(&turn_diff_tracker),
1662      );
1663      let max_retries = turn_context.provider.info().stream_max_retries();
1664      let mut retry_state = ResponsesStreamRetryState::default();
1665      let mut initial_input = Some(input);
1666      let mut original_input = None;
1667      let mut executed_tool_calls_by_output = HashMap::new();
1668      loop {
1669          // Running code-mode cells can request review while this response is in flight.
1670          // Keep the latest received ID until response.created replaces it.
1671          let prompt_input = if let Some(input) = initial_input.take() {
1672              input
1673          } else {
1674              sess.clone_history()
1675                  .await
1676                  .for_prompt(&step_context.settings.model_info.input_modalities)
1677          };
1678          let mut prompt_input = prompt_input;
1679          sess.services
1680              .executed_tool_calls
1681              .attach_to_prompt(&mut prompt_input, &mut executed_tool_calls_by_output);
1682          let mut prompt = build_prompt(
1683              prompt_input,
1684              step_context.as_ref(),
1685              base_instructions.clone(),
1686          );
1687          let responses_metadata = sess
1688              .responses_metadata(step_context.as_ref(), CodexResponsesRequestKind::Turn)
1689              .await;
1690          if crate::guardian::is_basic_session_source(&turn_context.session_source) {
1691              crate::guardian::prepare_guardian_prompt(
1692                  &sess,
1693                  &mut prompt,
1694                  step_context.as_ref(),
1695                  &responses_metadata,
1696              )
1697              .await?;
1698          }
1699          let err = match try_run_sampling_request(
1700              tool_runtime.clone(),
1701              Arc::clone(&sess),
1702              Arc::clone(&step_context),
1703              Arc::clone(&turn_store),
1704              client_session,
1705              &responses_metadata,
1706              Arc::clone(&turn_diff_tracker),
1707              &prompt,
1708              cancellation_token.child_token(),
1709          )
1710          .await
1711          {
1712              Ok(output) => {
1713                  return Ok((output, original_input.unwrap_or(prompt.input)));
1714              }
1715              Err(err) => match err.details() {
1716                  CodexErrorDetails::ContextWindowExceeded => {
1717                      sess.set_total_tokens_full(&turn_context).await;
1718                      return Err(err);
1719                  }
1720                  CodexErrorDetails::UsageLimitReached(e) => {
1721                      let rate_limits = e.rate_limits.clone();
1722                      if let Some(rate_limits) = rate_limits {
1723                          sess.update_rate_limits(&turn_context, *rate_limits).await;
1724                      }
1725                      return Err(err);
1726                  }
1727                  _ => err,
1728              },
1729          };
1730  
1731          let original_input = original_input.get_or_insert(prompt.input);
1732

125      pub async fn run<Rq, Out, T>(
126          &mut self,
127          tool: &mut T,
128          req: &Rq,
129          tool_ctx: &ToolCtx,
130      ) -> Result<OrchestratorRunResult<Out>, ToolError>
131      where
132          T: ToolRuntime<Rq, Out>,
