134          let turn_ctx = tool_ctx.step_context.turn.as_ref();
135          let approval_policy = tool_ctx.step_context.settings.approval_policy();
136          let otel = turn_ctx.session_telemetry.clone();
137          let otel_tn = flat_tool_name(&tool_ctx.tool_name).into_owned();
138          let otel_ci = &tool_ctx.call_id;
139          let strict_auto_review = turn_ctx.strict_auto_review_enabled();
140          // 1) Approval
141          let mut already_approved = false;
142  
143          let environment = tool.turn_environment(req);
144          let sandbox_manager = SandboxManager::new();
145          #[cfg(target_os = "macos")]
