147              environment
148                  .environment
149                  .local_runtime_paths()
150                  .and_then(|paths| paths.allowed_symlinked_codex_home.clone()),
151          );
152          let sandbox_config = environment.config();
153          let owner_network_policy = sandbox_config.network_policy.is_some();
154          let workspace_roots = environment.workspace_roots();
155          let executor_managed_process_sandbox = tool.uses_executor_managed_process_sandbox(req);
156          let permission_profile = environment.permission_profile();
157          let permissions = if executor_managed_process_sandbox {
158              // Executor-native roots remain symbolic until the executor applies its own sandbox.
159              permission_profile.clone()
160          } else {
161              environment.permission_profile_with_workspace_roots()
162          };
163          let file_system_sandbox_policy = permissions.file_system_sandbox_policy();
164          let requirement = tool.exec_approval_requirement(req).unwrap_or_else(|| {
165              default_exec_approval_requirement(approval_policy, &file_system_sandbox_policy)
166          });
167          match &requirement {
168              ExecApprovalRequirement::Skip { .. } => {
169                  if strict_auto_review {
170                      let action = tool
171                          .approval_action(req, &tool_ctx.call_id)
172                          .map_err(|err| {
173                              ToolError::Rejected(format!("could not prepare approval action: {err}"))
174                          })?;
175                      let approval_ctx = ApprovalContext {
176                          review_context: GuardianReviewContext::from(&tool_ctx.step_context),
177                          cancellation_token: Some(tool_ctx.cancellation_token.clone()),
178                          call_id: tool_ctx.call_id.clone(),
179                          tool_name: tool_ctx.tool_name.clone(),
180                          strict_auto_review,
