193                          otel_ci,
194                          &ReviewDecision::Approved,
195                          Some(ToolDecisionSource::Config),
196                      );
197                  }
198              }
199              ExecApprovalRequirement::Forbidden { reason } => {
200                  return Err(ToolError::Rejected(reason.clone()));
201              }
202              ExecApprovalRequirement::NeedsApproval { reason, .. } => {
203                  let action = tool
204                      .approval_action(req, &tool_ctx.call_id)
205                      .map_err(|err| {
206                          ToolError::Rejected(format!("could not prepare approval action: {err}"))
207                      })?;
208                  let approval_ctx = ApprovalContext {
209                      review_context: GuardianReviewContext::from(&tool_ctx.step_context),
210                      cancellation_token: Some(tool_ctx.cancellation_token.clone()),
211                      call_id: tool_ctx.call_id.clone(),
212                      tool_name: tool_ctx.tool_name.clone(),
