215                      retry_reason: None,
216                      network_approval_context: None,
217                  };
218                  tool_ctx
219                      .session
220                      .request_approval(action, approval_ctx)
221                      .await?;
222                  already_approved = true;
223              }
224          }
225  
226          // 2) First attempt under the selected sandbox.
227          let unsandboxed_allowed = unsandboxed_execution_allowed(&file_system_sandbox_policy);
228          let sandbox_override = sandbox_override_for_first_attempt(
229              tool.sandbox_permissions(req),
230              &requirement,
231              &file_system_sandbox_policy,
232              already_approved,
233          );
234          let (escalated_profile, writable_root_metadata) = if sandbox_override
235              == SandboxOverride::EscalatedSandboxWithRestrictions
236          {
237              let context = environment.sandbox_context(/*additional_permissions*/ None);
238              let policy_context = context.policy_context();
239              let baseline = permission_profile.file_system_sandbox_policy();
240              let file_system = baseline.for_approved_command(&policy_context);
