242                  file_system.can_write_path(&root, &policy_context)
243                      && PROTECTED_METADATA_PATH_NAMES.iter().any(|name| {
244                          root.join_descendant(name)
245                              .is_ok_and(|path| file_system.can_write_path(&path, &policy_context))
246                      })
247              });
248              let escalated_profile = (file_system != baseline
249                  && file_system
250                      != baseline.materialize_project_roots_with_path_uris(workspace_roots))
251              .then(|| {
252                  PermissionProfile::from_runtime_permissions_with_enforcement(
253                      permission_profile.enforcement(),
254                      &file_system,
255                      permission_profile.network_sandbox_policy(),
256                  )
257              });
258              (escalated_profile, writable_root_metadata)
259          } else {
260              (None, false)
261          };
262          if (escalated_profile.is_some() || writable_root_metadata)
263              && environment.environment.is_remote()
