289          let initial_permissions = escalated_local_profile
290              .as_ref()
291              .or(escalated_profile.as_ref())
292              .unwrap_or(&permissions);
293          let network_approval_spec = tool.network_approval_spec(req, tool_ctx);
294          // An explicit owner proxy requirement permits filtered egress, like an enabled
295          // controller proxy. Traffic-only owner policies stay offline unless command
296          // permissions grant networking.
297          // Preserve this baseline even when escalation skips the execution proxy, so retained
298          // terminals still record that their launch bypassed network restrictions.
