311                      || tool
312                          .sandbox_permissions(req)
313                          .requires_escalated_permissions())
314                      && effective_network_sandbox_policy(
315                          permission_profile.network_sandbox_policy(),
316                          network_approval_spec
317                              .as_ref()
318                              .and_then(|spec| spec.trigger.additional_permissions.as_ref()),
319                      )
320                      .is_enabled()
321          } else {
322              turn_ctx.network.is_some()
323          };
324          let sandbox_preference = tool.sandbox_preference();
325          let sandbox_requested = match sandbox_override {
326              SandboxOverride::BypassSandboxFirstAttempt => false,
327              SandboxOverride::NoOverride | SandboxOverride::EscalatedSandboxWithRestrictions => {
328                  sandbox_manager.should_sandbox(
329                      initial_permissions,
330                      sandbox_preference,
331                      managed_network_active,
332                  )
333              }
334          };
335          let windows_sandbox_type = codex_protocol::sandbox::effective_windows_sandbox_type(
336              sandbox_config.windows_sandbox_type,
337              sandbox_config.windows_sandbox_level,
338          );
339          let initial_sandbox = if sandbox_requested && !executor_managed_process_sandbox {
340              sandbox_manager.select_initial(
