365      let mut new_history = build_compacted_history(Vec::new(), &user_messages, &summary_text);
366      if let Some(summary_item) = new_history.last_mut() {
367          // This replacement history skips `record_conversation_items`; only the appended summary
368          // belongs to this compaction turn.
369          summary_item.set_turn_id_if_missing(&turn_context.sub_id);
370      }
371      let (window_number, window_ids) = sess.advance_auto_compact_window().await;
372  
373      let (initial_context, world_state_baseline) =
374          build_compaction_initial_context(sess.as_ref(), &initial_context_injection).await;
375      if !initial_context.is_empty() {
376          new_history =
377              insert_initial_context_before_last_real_user_or_summary(new_history, initial_context);
378      }
379      let reference_context_item = match initial_context_injection {
380          InitialContextInjection::DoNotInject => None,
381          InitialContextInjection::BeforeLastUserMessage { step_context, .. } => {
382              Some(step_context.to_turn_context_item())
383          }
384      };
385      sess.replace_compacted_history(
386          new_history,
387          reference_context_item,
388          world_state_baseline,
389          CompactedHistoryMetadata {
390              input_goal_ids,
391              message: summary_text,
392              window_number,
393              window_ids,
394              compaction_response_id: Some(compaction_response.response_id),
395              compaction_model_hash: turn_context.model_info().comp_hash.clone(),
396              reviewer_compaction_hash: None,
397          },
398      )
399      .await;
400      sess.recompute_token_usage(&turn_context).await;
401  
402      sess.emit_turn_item_completed(&turn_context, compaction_item)
403          .await;
404      let warning = EventMsg::Warning(WarningEvent {
405          message: "Heads up: Long threads and multiple compactions can cause the model to be less accurate. Start a new thread when possible to keep threads small and targeted.".to_string(),
406      });
407      sess.send_event(&turn_context, warning).await;
408      Ok(summary_suffix)
409  }
