551      fn record_item_with_metadata(
552          &mut self,
553          item: &ResponseItem,
554          metadata: Option<&CodexHarnessMetadata>,
555          policy: TruncationPolicy,
556      ) -> Option<codex_history::RetainedSource> {
557          if !is_api_message(item, metadata) {
558              return None;
559          }
560          let mut processed = ResponseItemEnvelope {
561              item: item.clone(),
562              metadata: metadata.cloned(),
563          };
564          if let ResponseItem::FunctionCallOutput { output, .. }
565          | ResponseItem::CustomToolCallOutput { output, .. } = &mut processed.item
566          {
567              // The override already includes the tool's serialization allowance.
568              let policy = metadata
569                  .and_then(|metadata| metadata.history_truncation_token_limit)
570                  .map(TruncationPolicy::Tokens)
571                  .unwrap_or_else(|| with_serialization_allowance(policy));
572              truncate_function_output_payload(output, policy, estimate_audio_token_count);
573          }
574          if let Some(review_history) = &mut self.review_history
575              && !is_guardian_context_message(item)
576          {
577              review_history.record(&processed);
578          }
579          if let Some(metadata) = metadata
580              && Arc::make_mut(&mut self.retained_context).record_sender_user_messages(metadata)
581          {
582              self.user_message_revision = self.user_message_revision.saturating_add(1);
583          }

