296    private async turn(): Promise<boolean> {
297      if (this.phase.kind !== 'running') {
298        this.throwError(new Error(`agent "${this.id}": turn without driver reservation`))
299      }
300      const phase = this.phase
301      const { signal } = phase.abort
302      signal.throwIfAborted()
303      const turn = phase.turn + 1
304      try {
305        this.session.append('turn/start', { turn })
306      } catch (error: unknown) {
307        this.throwError(error)
308      }
309      phase.turn = turn
310      let turnEnds: TurnEndReason | null = null
311      let target: InboxTarget = 'next-turn'
312      try {
313        while (true) {
314          signal.throwIfAborted()
315          const step = phase.step + 1
316          const decision = await this.preStep(target, { turn, step })
317          if (decision.kind === 'reject') {
318            turnEnds = { kind: 'blocked' }
319            return false
320          }
321          if (turnEnds && decision.messages.length === 0) break
322          // A removed waking message or an enter decision rewritten to empty
323          // still owns the initial turn boundary, but it spends no model call.
324          if (phase.step === 0 && decision.messages.length === 0) {
325            turnEnds = { kind: 'completed' }
326            return false
327          }
328          signal.throwIfAborted()
329          this.session.append('step/start', { turn, step })
330          phase.step = step
331          const toolRecovery = new ToolCallRecovery()
332          const stopRecovery = this.ctx.on('session/event', (session, event) => {
333            if (session === this.session) toolRecovery.observe(event)
334          })
335          try {
336            // max-tokens is sticky: once any step hits the ceiling, later steps
337            // that complete normally must not downgrade the turn outcome.
338            const stepEnd = await this.step(decision)
339            // max-tokens stays sticky: a later completed step must not
340            // downgrade the turn outcome.
341            if (turnEnds === null || turnEnds.kind !== 'max-tokens') turnEnds = stepEnd
342          } catch (error: unknown) {
343            try {
344              for (const event of toolRecovery.results()) {
345                this.session.append('tool/result', event.data, {
346                  surfaceOp: 'append',
347                  ...event.sourceEventSeqs === undefined ? {} : { sourceEventSeqs: event.sourceEventSeqs },
348                })
349              }
350            } catch (recoveryError: unknown) {
351              throw new AggregateError([error, recoveryError], 'Step failed and its pending tool results could not be recorded', { cause: error })
352            }
353            throw error
354          } finally {
355            stopRecovery()
356            this.session.append('step/end', { turn, step })
357          }
358          signal.throwIfAborted()
359          if (turnEnds && this.inbox.nextStep.length === 0) {
360            await this.dispatch.serial('agent/turn-stopping', { turn, signal })
361            signal.throwIfAborted()
362          }
363          if (turnEnds && this.inbox.nextStep.length === 0) break
364          target = 'next-step'
365        }
366      } catch (error: unknown) {
367        // A cause is present exactly while the signal is aborted.
368        const cause = abortedCancelCause(signal)
369        if (cause !== undefined) {
370          turnEnds = { kind: 'aborted', reason: cause }
371          throw error
372        }
373        // Every failure is structured: an `LlmError` keeps its facts, anything
374        // else flattens to `errorChain` text under the `UNKNOWN` code.
375        turnEnds = {
376          kind: 'error',
377          error: error instanceof LlmError
378            ? error.failure
379            : { message: errorChain(error), code: 'UNKNOWN' },
380        }
381        this.throwError(error)
382      } finally {

530          if (finish.kind === 'max-tokens') return { kind: 'max-tokens' }
