131  export function collapseOlderFunctionResponses(
132    history: Content[],
133    maxBytesPerOldResponse: number = COLLAPSED_FUNCTION_RESPONSE_MAX_BYTES,
134    segmenter: Intl.Segmenter = defaultGraphemeSegmenter,
135    protectedTurns: number = RECENT_TURNS_PROTECTED,
136    exemptTools: ReadonlySet<string> = RETRIEVAL_TOOL_NAMES_EXEMPT_FROM_COLLAPSE,
137  ): Content[] {
138    // Find all indices of user messages that contain functionResponse
139    const toolIndices: number[] = [];
140    for (let i = 0; i < history.length; i++) {
141      if (
142        history[i].role === 'user' &&
143        history[i].parts?.some((p) => !!p.functionResponse)
144      ) {
145        toolIndices.push(i);
146      }
147    }
148  
149    if (toolIndices.length <= protectedTurns) {
150      return history;
151    }
152  
153    // The last N tool indices represent recent tool turns that must be protected.
154    // Only prior tool indices are older completed turns eligible for collapsing.
155    const cutoffToolIndex = toolIndices[toolIndices.length - protectedTurns];
156  
157    const collapseString = (str: string): string => {
158      const totalBytes = Buffer.byteLength(str, 'utf8');
159      if (totalBytes <= maxBytesPerOldResponse) {
160        return str;
161      }
162  
163      const previewBytes = maxBytesPerOldResponse;
164      let preview = '';
165      let currentBytes = 0;
166  
167      for (const { segment } of segmenter.segment(str)) {
168        const segmentBytes = Buffer.byteLength(segment, 'utf8');
169        if (currentBytes + segmentBytes > previewBytes) {
170          break;
171        }
172        preview += segment;
173        currentBytes += segmentBytes;
174      }
175  
176      const omittedBytes = totalBytes - currentBytes;
177      return `${preview}\n... [Tool output collapsed from previous turn: ${omittedBytes} bytes omitted to conserve memory] ...`;
178    };
179  
180    const collapseValue = (val: unknown): unknown => {
181      if (typeof val === 'string') {
182        return collapseString(val);
183      }
184  
185      if (Array.isArray(val)) {
186        let arrayModified = false;
187        const newVal = val.map((item) => {
188          const collapsed = collapseValue(item);
189          if (collapsed !== item) {
190            arrayModified = true;
191          }
192          return collapsed;
193        });
194        return arrayModified ? newVal : val;
195      }
196  
197      if (typeof val === 'object' && val !== null) {
198        const proto: unknown = Object.getPrototypeOf(val);
199        if (proto !== Object.prototype && proto !== null) {
200          return val;
201        }
202  
203        let objModified = false;
204        const copy: Record<string, unknown> = {};
205        for (const [k, v] of Object.entries(val)) {
206          const collapsed = collapseValue(v);
207          if (collapsed !== v) {
208            objModified = true;
209          }
210          copy[k] = collapsed;
211        }
212        return objModified ? copy : val;
213      }
214  
215      return val;
216    };
217  
218    let modified = false;
219    const newHistory = history.map((content, idx) => {
220      // Only process older tool response turns before the protected recent window
221      if (idx >= cutoffToolIndex || content.role !== 'user' || !content.parts) {
222        return content;
223      }
224  
225      let partsModified = false;
226      const newParts = content.parts.map((part) => {
227        if (!part.functionResponse?.response) {
228          return part;
229        }
230  
231        // Exempt retrieval and file reading tools from collapsing
232        if (isExemptRetrievalTool(part.functionResponse.name, exemptTools)) {
233          return part;
234        }
235  
236        const resp: unknown = part.functionResponse.response;
237        const newResp = collapseValue(resp);
238  
239        if (newResp !== resp) {
240          partsModified = true;
241          return {
242            ...part,
243            functionResponse: {
244              // eslint-disable-next-line @typescript-eslint/no-misused-spread
245              ...part.functionResponse,
246              // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
247              response: newResp as Record<string, unknown>,
248            },
249          };
250        }
251  
252        return part;
253      });
254  
255      if (partsModified) {
256        modified = true;
257        return { ...content, parts: newParts };
258      }
259      return content;
260    });

467    async compress(
468      chat: GeminiChat,
469      promptId: string,
470      force: boolean,
471      model: string,
472      config: Config,
473      hasFailedCompressionAttempt: boolean,
474      abortSignal?: AbortSignal,
475    ): Promise<{ newHistory: Content[] | null; info: ChatCompressionInfo }> {
476      const curatedHistory = chat.getHistory(true);
477  
478      // Regardless of `force`, don't do anything if the history is empty.
479      if (curatedHistory.length === 0) {
480        return {
481          newHistory: null,
482          info: {
483            originalTokenCount: 0,
484            newTokenCount: 0,
485            compressionStatus: CompressionStatus.NOOP,
486          },
487        };
488      }
489  
490      // Fire PreCompress hook before compression
491      // This fires for both manual and auto compression attempts
492      const trigger = force ? PreCompressTrigger.Manual : PreCompressTrigger.Auto;
493      await config.getHookSystem()?.firePreCompressEvent(trigger);
494  
495      const lastPromptTokenCount = chat.getLastPromptTokenCount();
496      const originalTokenCount =
497        lastPromptTokenCount > 0
498          ? lastPromptTokenCount
499          : estimateTokenCountSync(curatedHistory.flatMap((c) => c.parts || []));
500  
501      // Don't compress if not forced and we are under the limit.
502      if (!force) {
503        const threshold =
504          (await config.getCompressionThreshold()) ??
505          DEFAULT_COMPRESSION_TOKEN_THRESHOLD;
506        const isOverModelThreshold =
507          originalTokenCount >= threshold * tokenLimit(model);
508  
509        if (!isOverModelThreshold) {
510          return {
511            newHistory: null,
512            info: {
513              originalTokenCount,
514              newTokenCount: originalTokenCount,
515              compressionStatus: CompressionStatus.NOOP,
516            },
517          };
518        }
519      }
520  
521      // Apply token-based truncation to the entire history before splitting.
522      // This ensures that even the "to compress" portion is within safe limits for the summarization model.
523      const truncatedHistory = await truncateHistoryToBudget(
524        curatedHistory,
525        config,
526      );
527  
528      // If summarization previously failed (and not forced), we only rely on truncation.
529      // We do NOT attempt to invoke the LLM for summarization again to avoid repeated failures/costs.
530      if (hasFailedCompressionAttempt && !force) {
531        const truncatedTokenCount = estimateTokenCountSync(
532          truncatedHistory.flatMap((c) => c.parts || []),
533        );
534  
535        // If truncation reduced the size, we consider it a successful "compression" (truncation only).
536        if (truncatedTokenCount < originalTokenCount) {
537          return {
538            newHistory: truncatedHistory,
539            info: {
540              originalTokenCount,
541              newTokenCount: truncatedTokenCount,
542              compressionStatus: CompressionStatus.CONTENT_TRUNCATED,
543            },
544          };
545        }
546  
547        return {
548          newHistory: null,
549          info: {
550            originalTokenCount,
551            newTokenCount: originalTokenCount,
552            compressionStatus: CompressionStatus.NOOP,
553          },
554        };
555      }
